package bastion

import (
	"context"
	_ "embed"
	"encoding/json"
	"errors"
	"log/slog"
	"strings"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/config"
	"github.com/aws/aws-sdk-go-v2/service/cloudformation"
	"github.com/aws/aws-sdk-go-v2/service/cloudformation/types"
	"github.com/aws/aws-sdk-go-v2/service/ec2"
	ec2Types "github.com/aws/aws-sdk-go-v2/service/ec2/types"
	"github.com/aws/aws-sdk-go-v2/service/ecs"
	ecsTypes "github.com/aws/aws-sdk-go-v2/service/ecs/types"
	"github.com/aws/aws-sdk-go-v2/service/rds"
	rdsTypes "github.com/aws/aws-sdk-go-v2/service/rds/types"
	"github.com/aws/smithy-go"
)

//go:embed stack.json
var raw []byte

type Bastion struct {
	DBS     []rdsTypes.DBInstance
	Task    *ecsTypes.Task
	Outputs map[string]string
}

func New() (*Bastion, error) {
	result := &Bastion{
		Outputs: map[string]string{},
	}
	var template map[string]interface{}
	err := json.Unmarshal(raw, &template)
	if err != nil {
		return nil, err
	}

	cfg, err := config.LoadDefaultConfig(context.Background())
	if err != nil {
		return nil, err
	}

	cfClient := cloudformation.NewFromConfig(cfg)
	ec2Client := ec2.NewFromConfig(cfg)
	rdsClient := rds.NewFromConfig(cfg)

	var vpcs *ec2.DescribeVpcsOutput
	var stack *types.Stack
	errorCh := make(chan error, 3)

	go func() {
		vpcs, err = ec2Client.DescribeVpcs(context.Background(), &ec2.DescribeVpcsInput{})
		errorCh <- err
	}()

	go func() {
		dbs, err := rdsClient.DescribeDBInstances(context.Background(), &rds.DescribeDBInstancesInput{})
		if err != nil {
			errorCh <- err
			return
		}
		result.DBS = dbs.DBInstances
		errorCh <- nil
	}()

	go func() {
		existing, err := cfClient.DescribeStacks(context.Background(), &cloudformation.DescribeStacksInput{
			StackName: aws.String("torpedo"),
		})
		var apiErr smithy.APIError
		if errors.As(err, &apiErr) && apiErr.ErrorCode() == "ValidationError" && apiErr.ErrorMessage() == "Stack with id torpedo does not exist" {
			errorCh <- nil
			return
		}
		if err == nil {
			stack = &existing.Stacks[0]
		}
		errorCh <- err
	}()

	for i := 0; i < cap(errorCh); i++ {
		if err := <-errorCh; err != nil {
			return nil, err
		}
	}

	resources := template["Resources"].(map[string]interface{})
	outputs := template["Outputs"].(map[string]interface{})
	for _, vpc := range vpcs.Vpcs {
		vpcID := strings.ReplaceAll(*vpc.VpcId, "-", "")
		resources["SecurityGroupFor"+vpcID] = map[string]interface{}{
			"Type": "AWS::EC2::SecurityGroup",
			"Properties": map[string]interface{}{
				"GroupName":        "torpedo-container-security-group-vpc-" + *vpc.VpcId,
				"GroupDescription": "torpedo security group for " + *vpc.VpcId,
				"VpcId":            *vpc.VpcId,
				"SecurityGroupIngress": []map[string]interface{}{
					{
						"IpProtocol": -1,
						"CidrIp":     "0.0.0.0/0",
					},
				},
			},
		}
		outputs["SecurityGroup"+vpcID] = map[string]interface{}{
			"Value": map[string]interface{}{"Fn::GetAtt": []string{"SecurityGroupFor" + vpcID,
				"GroupId"}},
		}
	}

	for _, db := range result.DBS {
		for _, sg := range db.VpcSecurityGroups {
			vpc := strings.ReplaceAll(*db.DBSubnetGroup.VpcId, "-", "")
			id := strings.ReplaceAll(*db.DBInstanceIdentifier, "-", "")
			resources["AllowRDS"+id] = map[string]interface{}{
				"Type": "AWS::EC2::SecurityGroupIngress",
				"Properties": map[string]interface{}{
					"Description": "torpedo route to database",
					"GroupId":     *sg.VpcSecurityGroupId,
					"IpProtocol":  -1,
					"SourceSecurityGroupId": map[string]interface{}{
						"Ref": "SecurityGroupFor" + vpc,
					},
				},
			}
		}
	}

	templateBody, err := json.Marshal(template)
	if err != nil {
		return nil, err
	}

	if stack != nil {
		_, err = cfClient.UpdateStack(context.Background(), &cloudformation.UpdateStackInput{
			StackName:    aws.String("torpedo"),
			TemplateBody: aws.String(string(templateBody)),
			Capabilities: []types.Capability{types.CapabilityCapabilityIam},
		})
		var apiErr smithy.APIError
		if errors.As(err, &apiErr) && apiErr.ErrorCode() == "ValidationError" && apiErr.ErrorMessage() == "No updates are to be performed." {
		} else if err != nil {
			return nil, err
		}
	} else {
		_, err = cfClient.CreateStack(context.Background(), &cloudformation.CreateStackInput{
			StackName:    aws.String("torpedo"),
			TemplateBody: aws.String(string(templateBody)),
			Capabilities: []types.Capability{types.CapabilityCapabilityIam},
		})
		if err != nil {
			return nil, err
		}
	}

	for {
		existing, err := cfClient.DescribeStacks(context.Background(), &cloudformation.DescribeStacksInput{
			StackName: aws.String("torpedo"),
		})
		if err != nil {
			return nil, err
		}
		if existing.Stacks[0].StackStatus == types.StackStatusCreateComplete || existing.Stacks[0].StackStatus == types.StackStatusUpdateComplete {
			stack = &existing.Stacks[0]
			break
		}
		if existing.Stacks[0].StackStatus == types.StackStatusCreateFailed || existing.Stacks[0].StackStatus == types.StackStatusUpdateRollbackComplete {
			return nil, errors.New("stack failed to create")
		}
		time.Sleep(1 * time.Second)
	}

	for _, output := range stack.Outputs {
		result.Outputs[*output.OutputKey] = *output.OutputValue
	}

	return result, nil
}

func (b *Bastion) Start(target rdsTypes.DBInstance, publicKey string) (*ecsTypes.Task, string, error) {
	cfg, err := config.LoadDefaultConfig(context.Background())
	ec2Client := ec2.NewFromConfig(cfg)
	ecsClient := ecs.NewFromConfig(cfg)

	describeSubnets, err := ec2Client.DescribeSubnets(context.Background(), &ec2.DescribeSubnetsInput{
		Filters: []ec2Types.Filter{
			{
				Name:   aws.String("vpc-id"),
				Values: []string{*target.DBSubnetGroup.VpcId},
			},
			{
				Name:   aws.String("mapPublicIpOnLaunch"),
				Values: []string{"true"},
			},
		},
	})
	if err != nil {
		return nil, "", err
	}

	subnets := []string{}
	for _, subnet := range describeSubnets.Subnets {

		subnets = append(subnets, *subnet.SubnetId)
	}
	vpcID := strings.ReplaceAll(*target.DBSubnetGroup.VpcId, "-", "")
	securityGroup := b.Outputs["SecurityGroup"+vpcID]
	task, err := ecsClient.RunTask(context.Background(), &ecs.RunTaskInput{
		LaunchType:     ecsTypes.LaunchTypeFargate,
		Cluster:        aws.String("TorpedoCluster"),
		TaskDefinition: aws.String("torpedo-bastion"),
		Overrides: &ecsTypes.TaskOverride{
			ContainerOverrides: []ecsTypes.ContainerOverride{
				{
					Name: aws.String("torpedo-bastion"),
					Environment: []ecsTypes.KeyValuePair{{
						Name:  aws.String("TORPEDO_PUBLIC_KEY"),
						Value: aws.String(publicKey),
					}},
				},
			},
		},
		NetworkConfiguration: &ecsTypes.NetworkConfiguration{
			AwsvpcConfiguration: &ecsTypes.AwsVpcConfiguration{
				SecurityGroups: []string{
					securityGroup,
				},
				Subnets:        subnets,
				AssignPublicIp: ecsTypes.AssignPublicIpEnabled,
			},
		},
	})
	if err != nil {
		return nil, "", err
	}

	for {
		describe, err := ecsClient.DescribeTasks(context.Background(), &ecs.DescribeTasksInput{
			Cluster: aws.String("TorpedoCluster"),
			Tasks:   []string{*task.Tasks[0].TaskArn},
		})
		if err != nil {
			return nil, "", err
		}
		if *describe.Tasks[0].LastStatus == "RUNNING" {
			eni := describe.Tasks[0].Attachments[0].Details[1].Value
			interfaces, err := ec2Client.DescribeNetworkInterfaces(context.Background(), &ec2.DescribeNetworkInterfacesInput{
				NetworkInterfaceIds: []string{*eni},
			})
			publicIP := *interfaces.NetworkInterfaces[0].Association.PublicIp
			if err != nil {
				return nil, "", err
			}
			b.Task = &describe.Tasks[0]
			return &describe.Tasks[0], publicIP, nil
		}
		time.Sleep(1 * time.Second)
	}
}

func (b *Bastion) Shutdown() error {
	slog.Info("bastion shutting down", "task", *b.Task.TaskArn)
	cfg, err := config.LoadDefaultConfig(context.Background())
	if err != nil {
		return err
	}
	ecsClient := ecs.NewFromConfig(cfg)
	_, err = ecsClient.StopTask(context.Background(), &ecs.StopTaskInput{
		Task:    b.Task.TaskArn,
		Cluster: aws.String("TorpedoCluster"),
	})
	if err != nil {
		return err
	}
	return nil
}

package main

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"log"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/briandowns/spinner"
	"github.com/fatih/color"
	"github.com/manifoldco/promptui"
	"github.com/thdxr/torpedo/pkg/bastion"
	"github.com/thdxr/torpedo/pkg/client"
	"github.com/thdxr/torpedo/pkg/server"
	cli "github.com/urfave/cli/v2"

	"log/slog"
)

func main() {

	app := &cli.App{
		Name:           "torpedo",
		Usage:          "A tool to access AWS resources behind a VPC",
		DefaultCommand: "client",
		Flags: []cli.Flag{
			&cli.BoolFlag{
				Name: "verbose",
			},
		},
		Before: func(c *cli.Context) error {
			level := slog.LevelWarn
			if c.Bool("verbose") {
				level = slog.LevelInfo
			}
			slog.SetDefault(
				slog.New(slog.NewTextHandler(os.Stderr, &slog.HandlerOptions{
					Level: level,
				})),
			)
			return nil
		},
		Commands: []*cli.Command{
			{
				Name:    "client",
				Aliases: []string{"c"},
				Usage:   "Run the client command",
				Flags: []cli.Flag{
					&cli.StringFlag{
						Name: "port",
					},
				},
				Action: func(cli *cli.Context) error {

					ctx, cancel := context.WithCancelCause(cli.Context)

					spin := spinner.New(spinner.CharSets[11], 100*time.Millisecond)
					spin.Color("yellow")
					c, err := client.NewClient()
					if err != nil {
						return err
					}

					slog.Info("searching for targets")

					spin.Suffix = " searching for targets (may take a while on first run)"
					spin.Start()

					b, err := bastion.New()
					if err != nil {
						spin.FinalMSG = "❌" + err.Error()
						spin.Stop()
						return err
					}

					if len(b.DBS) == 0 {
						spin.Stop()
						fmt.Println("no databases found")
						return errors.New("no databases found")
					}

					target := b.DBS[0]

					if len(b.DBS) > 1 {
						spin.Disable()
						options := make([]string, len(b.DBS))
						for i, db := range b.DBS {
							options[i] = *db.DBInstanceIdentifier
						}
						index, _, err := (&promptui.Select{
							Label:        "select database",
							Items:        options,
							HideHelp:     true,
							HideSelected: true,
						}).Run()
						if err != nil {
							return err
						}
						target = b.DBS[index]
						spin.Enable()
					}

					spin.Suffix = " starting proxy to " + color.BlueString(*target.DBInstanceIdentifier)
					slog.Info("starting bastion", "target", *target.DBInstanceIdentifier)
					_, ip, err := b.Start(target, c.PublicKey())
					if err != nil {
						return err
					}
					defer b.Shutdown()

					port := cli.String("port")
					if port == "" {
						port = fmt.Sprint(target.Endpoint.Port)
					}
					go func() {
						slog.Info("starting tunnel", "endpoint", *target.Endpoint.Address, "ip", ip)
						err = c.Start(
							client.ConnectConfig{
								Server:          ip + ":2222",
								DestinationHost: *target.Endpoint.Address,
								DestinationPort: fmt.Sprint(target.Endpoint.Port),
								BindPort:        port,
							},
						)
						if err != nil {
							cancel(err)
						}
					}()
					defer c.Shutdown()
					spin.Stop()
					fmt.Println("🚀 torpedo is ready")
					fmt.Println()
					fmt.Println("connect to port " + color.CyanString(port) + " on localhost")
					fmt.Println("it's forwarded to " + color.BlueString(*target.Endpoint.Address) + ":" + color.CyanString(fmt.Sprint(target.Endpoint.Port)))
					fmt.Println()
					fmt.Println("press ctrl+c to exit")
					fmt.Println()
					spin = spinner.New(spinner.CharSets[32], 100*time.Millisecond)
					spin.Start()

					sigCh := make(chan os.Signal, 1)
					signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
					select {
					case <-sigCh:
					case <-ctx.Done():
						spin.Stop()
						slog.Info("shutting down")
					}

					return context.Cause(ctx)
				},
			},
			{
				Name:    "server",
				Aliases: []string{"s"},
				Usage:   "Run the server command",
				Action: func(c *cli.Context) error {
					decoded, err := base64.StdEncoding.DecodeString(os.Getenv("TORPEDO_PUBLIC_KEY"))
					if err != nil {
						return err
					}
					server, err := server.NewServer(decoded)
					if err != nil {
						return err
					}
					server.Start()
					return nil
				},
			},
		},
	}

	err := app.Run(os.Args)
	if err != nil {
		log.Fatal(err)
	}

}

package server

import (
	"log"
	"net"

	"github.com/gliderlabs/ssh"
)

type Server struct {
	server *ssh.Server
}

func NewServer(publicRaw []byte) (*Server, error) {
	pub, err := ssh.ParsePublicKey(publicRaw)
	if err != nil {
		return nil, err
	}
	result := &Server{}

	result.server = &ssh.Server{
		PublicKeyHandler: func(ctx ssh.Context, key ssh.PublicKey) bool {
			compare := ssh.KeysEqual(pub, key)
			log.Println("public key matches", compare)
			return compare
		},
		LocalPortForwardingCallback: ssh.LocalPortForwardingCallback(func(ctx ssh.Context, dhost string, dport uint32) bool {
			log.Println("forwarding for", dhost, dport)
			return true
		}),
		ConnCallback: func(ctx ssh.Context, conn net.Conn) net.Conn {
			log.Println("connection from", conn.RemoteAddr())
			return conn
		},
		Addr: ":2222",
		Handler: ssh.Handler(func(s ssh.Session) {
			select {}
		}),
		ChannelHandlers: map[string]ssh.ChannelHandler{
			"session":      ssh.DefaultSessionHandler,
			"direct-tcpip": ssh.DirectTCPIPHandler,
		},
	}
	return result, nil
}

func (s *Server) Start() error {
	log.Println("starting server")
	err := s.server.ListenAndServe()
	if err != nil {
		return err
	}
	return nil
}

package client

import (
	"crypto/rand"
	"crypto/rsa"
	"encoding/base64"
	"fmt"
	"log/slog"

	"github.com/elliotchance/sshtunnel"
	"golang.org/x/crypto/ssh"
)

type Client struct {
	signer ssh.Signer
	tunnel *sshtunnel.SSHTunnel
}

func NewClient() (*Client, error) {
	privateKey, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return nil, err
	}
	signer, err := ssh.NewSignerFromKey(privateKey)
	if err != nil {
		return nil, err
	}

	return &Client{
		signer: signer,
	}, nil
}

type ConnectConfig struct {
	Server          string
	DestinationHost string
	DestinationPort string
	BindPort        string
}

func (c *Client) Start(cfg ConnectConfig) error {
	tunnel, err := sshtunnel.NewSSHTunnel(
		cfg.Server,
		ssh.PublicKeys(c.signer),
		fmt.Sprintf("%s:%s", cfg.DestinationHost, cfg.DestinationPort),
		cfg.BindPort,
	)
	c.tunnel = tunnel

	if err != nil {
		return err
	}
	err = tunnel.Start()
	if err != nil {
		return err
	}
	return nil
}

func (c *Client) PublicKey() string {
	return base64.StdEncoding.EncodeToString(
		c.signer.PublicKey().Marshal(),
	)
}

func (c *Client) Shutdown() error {
	slog.Info("tunnel shutting down")
	c.tunnel.Close()
	return nil
}
